1	import * as THREE from 'three';
2	import { mergeGeometries } from 'three/addons/utils/BufferGeometryUtils.js';
3	import { CONFIG, type VehicleTypeId } from '../../config';
4	
5	/* =====================================================================
6	   HÌNH HỌC XE CỘ — 3 loại (spec G1–G4): siêu xe, buýt nhỏ vàng, xe tay ga có người lái.
7	   Dựng theo mét, không chuẩn hóa: mũi xe về +X, rộng theo Z, mặt đường y = 0, tâm x = 0, z = 0.
8	   Số đo các bộ phận lấy từ bản dựng thử docs/superpowers/specs/tham-chieu/xe-co/xe-dung-thu.html (bỏ chi tiết không thấy ở 10 m).
9	   Mỗi đỉnh: position, normal (phẳng theo mặt), color (màu cố định ban ngày), aRole (xem Role). Có index, không uv, không texture.
10	   Mặt quấn ngược chiều kim đồng hồ nhìn từ ngoài (vật liệu FrontSide).
11	   ===================================================================== */
12	export enum Role { Fixed = 0, Paint = 1, Accent = 2, Head = 3, Tail = 4, Helmet = 5 }   // Paint: aPaint của instance; Accent: aAccent (áo); Helmet: aAccent.brg; Head/Tail: đèn; Fixed: color của đỉnh
13	export const VEHICLE_TYPES: VehicleTypeId[] = ['car', 'bus', 'bike'];
14	
15	const C = CONFIG.vehicles.palette;   // màu cố định (config.ts)
16	export type Sec = { x: number; w: number; y0: number; ym: number; y1: number; t?: number };   // mặt cắt loft: x, nửa rộng w, đáy y0, vai ym, nóc y1, nóc hẹp còn w·t
17	
18	/* Tập mặt đa giác lồi, mỗi mặt có đỉnh riêng ⇒ pháp tuyến phẳng; mặt tự lật để hướng ra xa điểm "inside" */
19	class Faces {
20	  p: number[] = []; n: number[] = []; idx: number[] = [];
21	  face(pts: THREE.Vector3[], inside: THREE.Vector3) {
22	    const nm = new THREE.Vector3(), ctr = new THREE.Vector3();
23	    for (let i = 0; i < pts.length; i++) {   // pháp tuyến Newell (đúng cả với tứ giác hơi vênh)
24	      const a = pts[i], b = pts[(i + 1) % pts.length];
25	      nm.x += (a.y - b.y) * (a.z + b.z); nm.y += (a.z - b.z) * (a.x + b.x); nm.z += (a.x - b.x) * (a.y + b.y); ctr.add(a);
26	    }
27	    ctr.divideScalar(pts.length);
28	    if (nm.dot(ctr.sub(inside)) < 0) { pts = [...pts].reverse(); nm.negate(); }
29	    nm.normalize();
30	    const base = this.p.length / 3;
31	    for (const v of pts) { this.p.push(v.x, v.y, v.z); this.n.push(nm.x, nm.y, nm.z); }
32	    for (let k = 1; k < pts.length - 1; k++) this.idx.push(base, base + k, base + k + 1);
33	  }
34	  geo(): THREE.BufferGeometry {
35	    const g = new THREE.BufferGeometry();
36	    g.setAttribute('position', new THREE.Float32BufferAttribute(this.p, 3)); g.setAttribute('normal', new THREE.Float32BufferAttribute(this.n, 3)); g.setIndex(this.idx);
37	    return g;
38	  }
39	}
40	const V = (x: number, y: number, z: number) => new THREE.Vector3(x, y, z);
41	
42	/* Vỏ lượn theo các mặt cắt dọc xe: mỗi mặt cắt là lục giác (đáy, vai, nóc hẹp), nối bằng tứ giác 4 đỉnh, bịt hai đầu */
43	export function vhLoft(st: Sec[]): THREE.BufferGeometry {
44	  const f = new Faces();
45	  const ring = (s: Sec) => { const t = s.t ?? 0.8; return [[-s.w, s.y0], [-s.w, s.ym], [-s.w * t, s.y1], [s.w * t, s.y1], [s.w, s.ym], [s.w, s.y0]].map(([z, y]) => V(s.x, y, z)); };
46	  const mid = (s: Sec) => V(s.x, (s.y0 + s.y1) / 2, 0), R = st.map(ring);
47	  for (let i = 0; i < R.length - 1; i++) {
48	    const inside = mid(st[i]).add(mid(st[i + 1])).multiplyScalar(0.5);
49	    for (let j = 0; j < 6; j++) { const k = (j + 1) % 6; f.face([R[i][j], R[i + 1][j], R[i + 1][k], R[i][k]], inside); }
50	  }
51	  f.face(R[0], mid(st[1])); f.face(R[R.length - 1], mid(st[st.length - 2]));
52	  return f.geo();
53	}
54	
55	/* Một bộ phận: bỏ uv + nhóm, gán màu đỉnh (null ⇒ trắng, màu thật lấy theo instance) và aRole */
56	function part(g: THREE.BufferGeometry, color: number | null, role: Role): THREE.BufferGeometry {
57	  if (g.getAttribute('uv')) g.deleteAttribute('uv'); g.clearGroups();
58	  const n = g.getAttribute('position').count, col = color === null ? new THREE.Color(1, 1, 1) : new THREE.Color(color), c = new Float32Array(n * 3), r = new Float32Array(n).fill(role);
59	  for (let i = 0; i < n; i++) { c[i * 3] = col.r; c[i * 3 + 1] = col.g; c[i * 3 + 2] = col.b; }
60	  g.setAttribute('color', new THREE.BufferAttribute(c, 3)); g.setAttribute('aRole', new THREE.BufferAttribute(r, 1));
61	  return g;
62	}
63	
64	/* Người dựng một loại xe: tích các bộ phận rồi gộp, đặt tâm x, z về 0 (không co giãn) */
65	class Kit {
66	  parts: THREE.BufferGeometry[] = [];
67	  add(g: THREE.BufferGeometry, color: number | null, role = Role.Fixed) { this.parts.push(part(g, color, role)); }
68	  box(sx: number, sy: number, sz: number, x: number, y: number, z: number, color: number | null, role = Role.Fixed, rz = 0) {
69	    const g = new THREE.BoxGeometry(sx, sy, sz); if (rz) g.rotateZ(rz); this.add(g.translate(x, y, z), color, role);
70	  }
71	  loft(st: Sec[], color: number | null, role = Role.Fixed) { this.add(vhLoft(st), color, role); }
72	  /* Bánh trụ 8 cạnh nằm phẳng trên đường (cạnh đáy cách tâm đúng r); chỉ mặt lốp + mặt ngoài (z = 0 ⇒ cả hai mặt) */
73	  wheel(r: number, w: number, x: number, z: number) {
74	    const f = new Faces(), R = r / Math.cos(Math.PI / 8), c = V(x, r, z);
75	    const ring = (dz: number) => Array.from({ length: 8 }, (_, i) => { const a = Math.PI / 8 + (i * Math.PI) / 4; return V(x + R * Math.cos(a), r + R * Math.sin(a), z + dz); });
76	    const A = ring(-w / 2), B = ring(w / 2);
77	    for (let i = 0; i < 8; i++) { const j = (i + 1) % 8; f.face([A[i], A[j], B[j], B[i]], c); }
78	    if (z >= 0) f.face(B, c); if (z <= 0) f.face(A, c);
79	    this.add(f.geo(), C.tyre);
80	  }

