  tourAll: tourAllBase,
  explore: { ...exploreBase, multi: multiParams },
  vehicles: vehiclesBase
};
export type SongHanConfig = typeof CONFIG.songHan;
export type HanTunnelConfig = typeof CONFIG.hanTunnel;

