  for (let i = 0; i < uv.count; i++) { const u = uv.getX(i), v = uv.getY(i); if (u <= 0.06 && v <= 0.06) solid++; else { assert.ok(v >= 0.1 && v <= 1 && u >= 0 && u <= 1, `uv tàu lá ${u}, ${v}`); frond++; } }
